from pysat.solvers import Glucose4
from pysat.card import CardEnc
import itertools

n = 28
min_deg = 4
max_deg = 7

def edge_var(u, v):
    if u > v:
        u, v = v, u
    return u * n + v + 1

solver = Glucose4()

# Degree constraints
for i in range(n):
    vars_i = [edge_var(i, j) for j in range(n) if i != j]
    # min degree
    cnf_min = CardEnc.atleast(lits=vars_i, bound=min_deg, encoding=1)
    for clause in cnf_min.clauses:
        solver.add_clause(clause)
    # max degree
    cnf_max = CardEnc.atmost(lits=vars_i, bound=max_deg, encoding=1)
    for clause in cnf_max.clauses:
        solver.add_clause(clause)

# No 3-cycles
for c in itertools.combinations(range(n), 3):
    solver.add_clause([-edge_var(c[0], c[1]), -edge_var(c[1], c[2]), -edge_var(c[0], c[2])])

# No 4-cycles
for c in itertools.combinations(range(n), 4):
    for p in itertools.permutations(c):
        if p[0] < p[1] and p[0] < p[2] and p[0] < p[3] and p[1] < p[3]:
            solver.add_clause([-edge_var(p[0], p[1]), -edge_var(p[1], p[2]), -edge_var(p[2], p[3]), -edge_var(p[3], p[0])])

# No 5-cycles
for c in itertools.combinations(range(n), 5):
    for p in itertools.permutations(c):
        # To avoid duplicates, fix the first element to be the minimum, and the second element < last element
        if p[0] == min(p) and p[1] < p[4]:
            solver.add_clause([-edge_var(p[0], p[1]), -edge_var(p[1], p[2]), -edge_var(p[2], p[3]), -edge_var(p[3], p[4]), -edge_var(p[4], p[0])])

print("Solving...")
if solver.solve():
    print("SAT")
    model = solver.get_model()
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            if model[edge_var(i, j) - 1] > 0:
                edges.append((i, j))
    print(edges)
else:
    print("UNSAT")

