G = nx.Graph()
G.add_nodes_from(range(28))
G.add_edges_from(edges)

degrees = [d for n, d in G.degree()]
print("Min degree:", min(degrees))
print("Max degree:", max(degrees))

try:
    cycles = nx.minimum_cycle_basis(G)
    min_cycle_len = min(len(c) for c in cycles) if cycles else float('inf')
    print("Girth (from cycle basis):", min_cycle_len)
except:
    pass

def get_girth(G):
    girth = float('inf')
    for n in G.nodes():
        # BFS to find shortest cycle
        dist = {n: 0}
        parent = {n: None}
        q = [n]
        while q:
            u = q.pop(0)
            for v in G.neighbors(u):
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v:
                    girth = min(girth, dist[u] + dist[v] + 1)
    return girth

print("Girth (BFS):", get_girth(G))
